// Clean an LLM response string and parse it as JSON
function cleanAndParse(str) {
  if (typeof str !== 'string') return str;

  let s = str.trim();

  // Remove markdown code fences: ```json ... ``` or ``` ... ```
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

  // Some LLMs return literal "\n" text instead of real newlines
  s = s.replace(/\\n/g, ' ');

  // Keep only the part from the first { to the last }
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start !== -1 && end !== -1) {
    s = s.substring(start, end + 1);
  }

  return JSON.parse(s);
}

return items.map(item => {
  let data = item.json;

  try {
    // The LLM output may sit in different fields
    const candidates = [data.text, data.output, data.result, data.response];
    const raw = candidates.find(v => typeof v === 'string');

    if (raw) {
      data = cleanAndParse(raw);
    } else if (typeof data === 'string') {
      data = cleanAndParse(data);
    }

    // Normalise and validate email
    const email = String(data.Email || '').trim().toLowerCase();
    data.Email = email;
    data.Email_Valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

    return { json: data };
  } catch (err) {
    return {
      json: {
        error: 'Invalid JSON',
        message: err.message,
        raw: item.json
      }
    };
  }
});
